<?php
require (dirname(__DIR__, 3) . '/app/Bootstrap/bootstrap.php');$p=Database::pdo();
$p->exec("CREATE TABLE IF NOT EXISTS marketplace_stock_snapshots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_id VARCHAR(120) NOT NULL,product_id VARCHAR(100) NOT NULL,variant_id VARCHAR(100) NOT NULL,warehouse_id VARCHAR(100) NOT NULL DEFAULT '',quantity DECIMAL(16,3) NULL,observed_at DATETIME NOT NULL,KEY stock_snapshot_lookup(store_id,product_id,variant_id,warehouse_id,observed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$p->exec("CREATE TABLE IF NOT EXISTS marketplace_stock_minimums (store_id VARCHAR(120) NOT NULL,product_id VARCHAR(100) NOT NULL,variant_id VARCHAR(100) NOT NULL,warehouse_id VARCHAR(100) NOT NULL DEFAULT '',minimum_qty DECIMAL(16,3) NOT NULL,changed_by VARCHAR(120) NOT NULL,changed_at DATETIME NOT NULL,PRIMARY KEY(store_id,product_id,variant_id,warehouse_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$p->exec("CREATE TABLE IF NOT EXISTS marketplace_stock_minimum_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_key VARCHAR(120) NOT NULL,store_id VARCHAR(120) NOT NULL,product_id VARCHAR(100) NOT NULL,variant_id VARCHAR(100) NOT NULL,warehouse_id VARCHAR(100) NOT NULL,previous_qty DECIMAL(16,3) NULL,new_qty DECIMAL(16,3) NOT NULL,actor VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");echo "Marketplace stock schema ready.\n";
